// binding is one key the dashboard itself handles: where it works, how
// it is typed, what the key bar and the help say about it, and what the
// keys doc says. The table below is the single source for the key bar,
// the help overlay and docs/keys.md (generated by keys_test.go), and a
// test checks the handlers in app.go and fortress.go against it, so the
// three can no longer drift apart. "issue" is the detail view of an
// issue: a view for the bar, the same handler as detail.
type binding struct {
	Views  []string      // ViewList, ViewDetail, "issue", ViewFiles, ViewPatch, ViewFortress, "any"
	Keys   []widgets.Key // Keys[0] is the primary; the rest are aliases
	Bar    string        // the key-bar chip; "" keeps it out of the bar
	Label  string        // the key-bar label; Labels overrides it per view
	Labels map[string]string
	Help   string // the help overlay text; "" keeps it out of the help
	Group  string // help/doc group: nav, list, detail, files, diff, fortress, any
	Prio   int    // bar trim: higher drops first; 0 never drops
	Doc    string // docs/keys.md prose; "" uses Help
	// wfBefore marks where a view's workflow keys slot in: before this
	// binding (after the view's own actions, before the utilities).
	wfBefore bool
	// when gates the bar chip (D in the list needs a deploy provider).
	when func(*Model) bool
	// Do handles the key (lock held): the view's action. page is the
	// view's page height; app is the action goroutine's handle.
	Do func(m *Model, k widgets.Key, page int, app *lockedApp) tea.Cmd
}

// R and K build keys; S spells one for the doc.
var (
	R = widgets.R
	K = widgets.K
)

const anyView = "any"

