// providesDeploys gates D in the list bar.
func (m *Model) providesDeploys() bool { return m.wf.ProvidesDeploys() }

// keymap is the dispatch table: view -> key -> binding, built once from
// bindings ("any" rows under anyView; a view's own row wins).
var keymap = func() map[string]map[widgets.Key]*binding {
	km := map[string]map[widgets.Key]*binding{}
	for i := range bindings {
		b := &bindings[i]
		for _, v := range b.Views {
			if km[v] == nil {
				km[v] = map[widgets.Key]*binding{}
			}
			for _, k := range b.Keys {
				km[v][k] = b
			}
		}
	}
	return km
}()

// lookup finds the binding for k in view: the view's own, else an
// "any" one; the issue view falls back to the detail's (its actions
// refuse an issue with a reason, which beats silence).
func lookup(view string, k widgets.Key) *binding {
	if b := keymap[view][k]; b != nil {
		return b
	}
	if view == "issue" {
		if b := keymap[ViewDetail][k]; b != nil {
			return b
		}
	}
	return keymap[anyView][k]
}

// has reports whether the binding applies in view.
func (b *binding) has(view string) bool {
	for _, v := range b.Views {
		if v == view || v == anyView {
			return true
		}
	}
	return false
}

// barLabel is the chip's label in view.
func (b *binding) barLabel(view string) string {
	if l, ok := b.Labels[view]; ok {
		return l
	}
	return b.Label
}

// barItem is one key-bar chip with its trim priority.
type barItem struct {
	key, label string
	prio       int
}

// barFor is the key bar of a view, in table order, the workflows' keys
// spliced in after the view's actions, ending with q (or back). The
// bar's "? help" chip is appended by drawKeys.
func (m *Model) barFor(view string) []barItem {
	var out []barItem
	wf := m.wf.Keys(view)
	if view == "issue" {
		wf = nil
	}
	spliced := false
	splice := func() {
		if spliced {
			return
		}
		spliced = true
		for _, k := range wf {
			out = append(out, barItem{k.Ch, k.Label, max(1, k.Priority)})
		}
	}
	for i := range bindings {
		b := &bindings[i]
		if !b.has(view) || b.Bar == "" {
			continue
		}
		if b.when != nil && !b.when(m) {
			continue
		}
		if b.wfBefore {
			splice()
		}
		key := b.Bar
		if key == "↵" && glyphs.Active() == glyphs.ASCII {
			key = "enter"
		}
		out = append(out, barItem{key, b.barLabel(view), b.Prio})
	}
	splice()
	return out
}

// keysFor is barFor as [key, label] pairs (the tests read it).
func (m *Model) keysFor(view string) [][2]string {
	var out [][2]string
	for _, it := range m.barFor(view) {
		out = append(out, [2]string{it.key, it.label})
	}
	return out
}

// trimBar drops chips until the bar fits width: the highest priority
// first (ties: the rightmost), never priority 0 (q, ?). width counts the
// chip's own cells: " key " + " label ".
func trimBar(items []barItem, width int, cells func(barItem) int) []barItem {
	out := append([]barItem(nil), items...)
	total := 0
	for _, it := range out {
		total += cells(it)
	}
	for total > width {
		drop, prio := -1, 0
		for i, it := range out {
			if it.prio > 0 && it.prio >= prio {
				drop, prio = i, it.prio
			}
		}
		if drop < 0 {
			break
		}
		total -= cells(out[drop])
		out = append(out[:drop], out[drop+1:]...)
	}
	return out
}

// helpGroup is one labeled block of the help overlay: entries the
// drawer packs whole onto lines (packEntries).
type helpGroup struct {
	label   string
	entries []string
}

// helpGroupOrder is the overlay's order; workflow rows go after detail.
var helpGroupOrder = []string{"list", "detail", "files", "diff", "fortress", "any"}

var helpGroupLabels = map[string]string{
	"list": "list", "detail": "detail", "files": "files", "diff": "diff", "fortress": "fortress", "any": "anywhere",
}

// helpGroups is the help text per group, from the table. Navigation
// entries join the first group that uses them (list, detail).
func helpGroups() []helpGroup {
	byGroup := map[string][]string{}
	seen := map[string]bool{}
	for i := range bindings {
		b := &bindings[i]
		if b.Help == "" || seen[b.Group+"|"+b.Help] {
			continue
		}
		seen[b.Group+"|"+b.Help] = true
		g := b.Group
		if g == "nav" {
			g = "list"
			if b.has(ViewDetail) && !b.has(ViewList) {
				g = "detail"
			}
		}
		byGroup[g] = append(byGroup[g], b.Help)
	}
	var out []helpGroup
	for _, g := range helpGroupOrder {
		if len(byGroup[g]) == 0 {
			continue
		}
		out = append(out, helpGroup{helpGroupLabels[g], byGroup[g]})
	}
	out = append(out, helpGroup{"prompts", []string{"enter submits", "esc / ctrl-c cancels", "^U ^W ^K edit", "menus: j/k, 1-9", "confirms: y, anything else is no"}})
	return out
}

// packEntries lays entries onto lines of at most width cells, three
// spaces apart, each entry whole; an entry wider than the line gets
// word-wrapped on its own.
func packEntries(entries []string, width int) []string {
	var lines []string
	cur := ""
	flush := func() {
		if cur != "" {
			lines = append(lines, cur)
			cur = ""
		}
	}
	for _, e := range entries {
		if text.Width(e) > width {
			flush()
			lines = append(lines, widgets.Wrap(e, width)...)
			continue
		}
		if cur == "" {
			cur = e
		} else if text.Width(cur)+3+text.Width(e) <= width {
			cur += "   " + e
		} else {
			flush()
			cur = e
		}
	}
	flush()
	return lines
}

// coreKeyIDs is every view:key the dashboard binds, the shape the
// workflow package reserves (workflow.CoreKeyIDs), so a test can keep
// the two lists equal.
func coreKeyIDs() []string {
	set := map[string]bool{}
	for i := range bindings {
		b := &bindings[i]
		for _, v := range b.Views {
			if v != ViewList && v != ViewDetail && v != "issue" && v != anyView {
				continue
			}
			for _, k := range b.Keys {
				if k.Rune != 0 && k.Rune != ' ' {
					set[v+":"+string(k.Rune)] = true
				}
			}
		}
	}
	out := make([]string, 0, len(set))
	for k := range set {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// docViews names a binding's views for the keys doc.
func docViews(b *binding) string {
	var names []string
	for _, v := range b.Views {
		switch v {
		case "issue":
			if b.has(ViewDetail) {
				continue
			}
			names = append(names, "issue")
		case ViewPatch:
			names = append(names, "diff")
		default:
			names = append(names, v)
		}
	}
	return strings.Join(names, ", ")
}

// docKey spells a binding's keys for the doc.
func docKey(b *binding) string {
	var parts []string
	for _, k := range b.Keys {
		switch {
		case k.Rune == ' ':
			parts = append(parts, "space")
		case k.Rune != 0:
			parts = append(parts, "`"+string(k.Rune)+"`")
		case k.Name == "up" || k.Name == "down" || k.Name == "left" || k.Name == "right", k.Name == "backtab":
			continue // "arrows too" is in the prose; backtab is shift+tab's other name
		default:
			parts = append(parts, k.Name)
		}
	}
	return strings.Join(parts, " / ")
}

// KeysDoc renders docs/keys.md from the table; keys_test.go keeps the
// file equal to it (go test ./internal/ui -update rewrites it).
func KeysDoc() string {
	var b strings.Builder
	b.WriteString("# Keys\n\n")
	b.WriteString("<!-- generated from internal/ui/keys.go by `go test ./internal/ui -update`; edit the table, not this file -->\n\n")
	b.WriteString("| View | Key | Action |\n|---|---|---|\n")
	for i := range bindings {
		bd := &bindings[i]
		doc := bd.Doc
		if doc == "" {
			continue
		}
		b.WriteString("| " + docViews(bd) + " | " + docKey(bd) + " | " + doc + " |\n")
	}
	b.WriteString("| list, detail | `w` | with `maintenance_window`: `/attend`, `/release` or `/window-cancel` on the night's manifest issue, or open it |\n")
	b.WriteString("| prompts | enter / esc | submit / cancel (Ctrl-C and Ctrl-G cancel too). Ctrl-U, Ctrl-W, Ctrl-K, Ctrl-A/E, arrows, Home/End edit the line; a paste inserts as one edit. A prompt with a minimum length (a reason) counts down and refuses enter until it is met |\n")
	b.WriteString("| menus | `j`/`k` + enter, `1`–`9` | choose; esc, `q`, Ctrl-C cancel |\n")
	b.WriteString("| confirms | `y` | anything else is no |\n")
	b.WriteString("\nEsc never quits the list: Alt+key and some terminals' Ctrl+arrow sequences\nbegin with an escape, so a stray one must never quit.\n")
	return b.String()
}
